// T16-R4 m-6: the _INDEX "Findings routed (W1-driving)" per-case table is
// generated by a committed script, so a reader can re-run it. The committed
// table is the expectation (it is reviewed evidence, re-derived by the T16
// reviewer's own script), never this module's output. Synthetic rows pin the
// selection, the order, the error-red rendering and every refusal.
// Sport-independent: TRIAGE rows and stored check verdicts, keyed by case id.
import { mkdtempSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { FindingsRefused, findings, main, renderFindings, shortRule, triageRows, type RunLike, type TriageRow } from "../findings-table.ts";
import { parseResults } from "../lib/results.ts";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const PROMPTS = join(REPO, "docs/superpowers/specs/2026-09-27-format-matrix-prompts");
const TRUTH_RUNS = join(PROMPTS, "truth-runs");
const TRIAGE = join(TRUTH_RUNS, "w1drv-l3/TRIAGE.md");
const HEADER = "| wave | TRIAGE # | case | failing checks (on the run it is judged on) | judged on | rule |";

/** The table _INDEX commits: its header line through the last table line. */
function committedTable(): string {
  const lines = readFileSync(join(PROMPTS, "_INDEX.md"), "utf8").split("\n");
  const at = lines.indexOf(HEADER);
  expect(at, "_INDEX has no generated findings table").toBeGreaterThan(-1);
  const end = lines.findIndex((l, i) => i > at && !l.startsWith("|"));
  return lines.slice(at, end).join("\n") + "\n";
}
const loadCommitted = (run: string): RunLike => parseResults(JSON.parse(readFileSync(join(TRUTH_RUNS, run, "results.json"), "utf8")));

const SHA = "abcdef012";
const tri = (n: number, caseId: string, finalClass: string, wave: string, rule = "P9 a rule (detail)", judged = `run-a @ ${SHA}`): TriageRow =>
  ({ n, caseId, judged, finalClass, wave, rule });
const kase = (caseId: string, state: string, failing: string[], reason = "a reason") =>
  ({ caseId, state, reason, checks: [...failing.map((id) => ({ id, verdict: "fail" })), { id: "passes", verdict: "pass" }] });
const run = (cases: RunLike["cases"], harnessCommit = SHA): RunLike => ({ harnessCommit, cases });

describe("findings-table (T16-R4 m-6)", () => {
  it("the empty case first: no product row is refused, and so is a TRIAGE with no 'Every ❌' section", () => {
    expect(() => findings([], () => run([]))).toThrow(FindingsRefused);
    expect(() => findings([tri(1, "a|x|y|F1", "works", "—")], () => run([]))).toThrow(/no product row among 1/);
    expect(() => triageRows("# TRIAGE\n\nnothing here\n")).toThrow(/no "## Every ❌" section/);
  });

  it("takes product rows only, reads the failing checks from the judged run (not TRIAGE's column), elides UUIDs in an error red, and sorts by wave number then TRIAGE number", () => {
    const rows = [
      tri(1, "a|x|y|F1", "product", "W7"),
      tri(2, "b|x|y|F1", "works", "—"),
      tri(3, "c|x|y|R4", "product", "W10 (lane)"),
      tri(4, "d|x|y|M1", "product", "W2 (T15-R4; T6-R1 had W4)"),
      tri(5, "e|x|y|M1", "product", "W2", "P1 x", `run-b/sub @ ${SHA}`),
    ];
    let loads = 0;
    const f = findings(rows, (r) => {
      loads++;
      return r === "run-a"
        ? run([kase("a|x|y|F1", "red", ["I2-one", "I4-two"]), kase("b|x|y|F1", "works", []), kase("c|x|y|R4", "red", ["I9"]), kase("d|x|y|M1", "red", [], "error: POST /x/0e0a6bd2-1b8a-4c3c-9d7e-1234567890ab → 500")])
        : run([kase("e|x|y|M1", "red", ["life-loop-bounded"])]);
    });
    expect(f.rows.map((r) => [r.wave, r.n])).toEqual([["W2", 4], ["W2", 5], ["W7", 1], ["W10", 3]]);
    expect(f.rows.find((r) => r.n === 1)?.failing).toEqual(["I2-one", "I4-two"]);
    expect(f.rows.find((r) => r.n === 4)?.failing).toEqual(["error red — POST /x/<id> → 500"]);
    expect(f.byWave).toEqual({ W2: 2, W7: 1, W10: 1 });
    // Each run is read once, however many rows it judges.
    expect([f.files, loads]).toEqual([2, 2]);
    const md = renderFindings(f.rows).split("\n");
    expect(md[0]).toBe(HEADER);
    expect(md[2]).toBe("| W2 | 4 | `d\\|x\\|y\\|M1` | error red — POST /x/<id> → 500 | `run-a` | P9 a rule |");
    expect(md.length).toBe(2 + 4 + 1);
  });

  it("refuses, by name: a judged-on cell it cannot parse, a harness that differs, a case missing or not red, a red with no failing check and no error reason, a wave that is not W2..W10", () => {
    const one = (row: TriageRow, r: RunLike) => () => findings([row], () => r);
    const red = run([kase("a|x|y|F1", "red", ["I2"])]);
    expect(one(tri(1, "a|x|y|F1", "product", "W2", "r", "run-a"), red)).toThrow(/row 1: judged-on not parsed/);
    expect(one(tri(1, "a|x|y|F1", "product", "W2"), run(red.cases, "000000000"))).toThrow(/ran at 000000000, TRIAGE says abcdef012/);
    expect(one(tri(1, "z|x|y|F1", "product", "W2"), red)).toThrow(/z\|x\|y\|F1 is not in run-a/);
    expect(one(tri(1, "a|x|y|F1", "product", "W2"), run([kase("a|x|y|F1", "works", [])]))).toThrow(/is works on run-a, TRIAGE says product/);
    expect(one(tri(1, "a|x|y|F1", "product", "W2"), run([kase("a|x|y|F1", "red", [], "vacuous: nothing")]))).toThrow(/no failing check and no error reason/);
    expect(one(tri(1, "a|x|y|F1", "product", "W1-driving"), red)).toThrow(/wave 'W1-driving' is not a product wave/);
    expect(one(tri(1, "a|x|y|F1", "product", "—"), red)).toThrow(/is not a product wave/);
  });

  it("shortens the rule as the doc prints it: a product rule to its name, a coverage-table signature to 'table: …'", () => {
    expect(shortRule("P1 bracket draw stall (engine supportsDraws: boardgame) — T6-R1 F-A")).toBe("P1 bracket draw stall");
    expect(shortRule("coverage table (predicted): mexicano-pair-entrants-counted-as-players (self-pair) [now failing: x]")).toBe("table: self-pair");
    expect(shortRule("coverage table (predicted): r4-withdrawn-player-kept-playing")).toBe("table: kept-playing");
  });

  it("the committed evidence: over truth-runs/w1drv-l3/TRIAGE.md and the committed results, the script reproduces _INDEX's table exactly — every product row, each read from its judged run", () => {
    const rows = triageRows(readFileSync(TRIAGE, "utf8"));
    const product = rows.filter((r) => r.finalClass === "product").length;
    expect(product, "TRIAGE has no product row — the check would be vacuous").toBeGreaterThan(0);
    const f = findings(rows, loadCommitted);
    expect(f.rows.length).toBe(product);
    expect(renderFindings(f.rows)).toBe(committedTable());
    console.info(`findings table: ${f.rows.length} product rows of ${rows.length}, ${f.files} results files, ${JSON.stringify(f.byWave)}`);
  });

  it("the CLI: 0 writes the table (twice, identically); 2 is usage; 3 an unreadable TRIAGE; 1 a refusal, with nothing written", () => {
    const dir = mkdtempSync(join(tmpdir(), "findings-"));
    const out = join(dir, "a", "t.md");
    expect(main([TRIAGE, TRUTH_RUNS, "--out", out])).toBe(0);
    const first = readFileSync(out, "utf8");
    expect(first).toBe(committedTable());
    expect(main([TRIAGE, TRUTH_RUNS, "--out", out])).toBe(0);
    expect(readFileSync(out, "utf8")).toBe(first);
    expect(main([])).toBe(2);
    expect(main([TRIAGE])).toBe(2);
    expect(main([TRIAGE, TRUTH_RUNS, "--bogus"])).toBe(2);
    expect(main([join(dir, "missing.md"), TRUTH_RUNS])).toBe(3);
    // A product row whose run is not on disk: unreadable input, nothing written.
    const lost = join(dir, "lost.md");
    writeFileSync(lost, `## Every ❌\n\n| 1 | \`a\\|x\\|y\\|F1\` | I2 | — | nowhere-run @ ${SHA} | product | W2 | P1 x |\n`);
    const out3 = join(dir, "b", "t.md");
    expect(main([lost, TRUTH_RUNS, "--out", out3])).toBe(3);
    expect(existsSync(out3)).toBe(false);
    // No product row: refused, nothing written.
    const none = join(dir, "none.md");
    writeFileSync(none, `## Every ❌\n\n| 1 | \`a\\|x\\|y\\|F1\` | I2 | — | — | works | — | — |\n`);
    const out1 = join(dir, "c", "t.md");
    expect(main([none, TRUTH_RUNS, "--out", out1])).toBe(1);
    expect(existsSync(out1)).toBe(false);
  });
});
